import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Панель и модерация","description":"","frontmatter":{"pageId":"admins/administration","contentRevision":1},"headers":[],"relativePath":"ru/admins/administration.md","filePath":"ru/admins/administration.md"}'),o={name:"ru/admins/administration.md"};function l(n,a,s,d,c,m){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="панель-и-модерация" tabindex="-1">Панель и модерация <a class="header-anchor" href="#панель-и-модерация" aria-label="Permalink to &quot;Панель и модерация&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Открой HTTPS /admin/ и войди legacy Admin:ApiToken. Панель показывает игроков, состояние, экономику, рейды и журнал действий. Для интеграций используй API с отдельным токеном, а не копию cookie.</p><p>Начинай с чтения player/status/actions и уточнения id. Kick разрывает сессию; mute ограничивает чат; ban запрещает вход; economy freeze и raids freeze управляют отдельными подсистемами. Причину фиксируй в аудите.</p><p>Rollback выбирает конкретную версию сейва; reset создаёт новую линию колонии и очищает связанные разрешения. Archive сохраняет колонию отдельно, restore-colony восстанавливает архив при проверке контекста. Coop rollback очищает назначения пешек; отзыв членства завершает сессию. Для влияния администратор может отозвать публикацию с ожидаемой версией, но не включить за игрока.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Reset, rollback, recreateworld и restore имеют разрушительные последствия: сначала подтверждение и проверенная резервная копия. Не компенсируй сбой простым wallet +n до проверки эскроу. Размораживание не исправляет повреждённый сейв.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./cli">Справочник CLI</a></li><li><a href="./api">Справочник REST API</a></li><li><a href="./backup-recovery">Резервные копии и восстановление</a></li></ul>',10)])])}const u=e(o,[["render",l]]);export{h as __pageData,u as default};
